def solve():
    results = []
    for g1 in range(2, 100):
        for g2 in range(2, 100):
            # g1 + g2 = g3 * g4 - 840
            # g3 * g4 = g1 + g2 + 840
            target = g1 + g2 + 840
            # We need to find g3, g4 such that g3 * g4 = target and g3, g4 >= 2.
            # Also, let's check if g3, g4 <= 100 (they should be small).
            for g3 in range(2, 100):
                if target % g3 == 0:
                    g4 = target // g3
                    if g4 >= 2:
                        # Now we have g1, g2, g3, g4.
                        # We can continue the sequence.
                        seq = [g1, g2, g3, g4]
                        valid = True
                        for i in range(len(seq) - 3):
                            # seq[i] + seq[i+1] = seq[i+2] * seq[i+3] - 840
                            # So seq[i+2] * seq[i+3] = seq[i] + seq[i+1] + 840
                            # We need to find seq[i+4] such that seq[i+3] * seq[i+4] = seq[i+1] + seq[i+2] + 840
                            target_next = seq[i+1] + seq[i+2] + 840
                            # We need seq[i+3] * seq[i+4] = target_next.
                            # Thus seq[i+4] = target_next / seq[i+3].
                            if target_next % seq[i+3] == 0:
                                next_val = target_next // seq[i+3]
                                if next_val >= 2:
                                    seq.append(next_val)
                                else:
                                    valid = False
                                    break
                            else:
                                valid = False
                                break

                        # If we successfully built a long sequence, let's check it.
                        # A sequence is "stable" if it doesn't explode.
                        if valid and len(seq) > 10:
                            if all(x <= 100 for x in seq):
                                results.append(seq)
    return results

print(solve())

def solve_large():
    results = []
    # Since g1, g2 could be large, let's think about the constraints.
    # g3*g4 = g1+g2+840
    # g4*g5 = g2+g3+840
    # g5*g6 = g3+g4+840
    # If g_i are large, g_{i+2}g_{i+3} \approx g_i + g_{i+1}.
    # This means the sequence must decrease or stay small.
    # If it stays large, let g_i \approx X.
    # X^2 \approx 2X + 840 => X^2 - 2X - 840 \approx 0 => X \approx 30.
    # So g_i should be around 30.
    # Let's check g1, g2 in a larger range.
    for g1 in range(2, 200):
        for g2 in range(2, 200):
            target = g1 + g2 + 840
            for g3 in range(2, 200):
                if target % g3 == 0:
                    g4 = target // g3
                    if g4 >= 2 and g4 < 200:
                        seq = [g1, g2, g3, g4]
                        valid = True
                        for i in range(len(seq) - 3):
                            target_next = seq[i+1] + seq[i+2] + 840
                            if target_next % seq[i+3] == 0:
                                next_val = target_next // seq[i+3]
                                if 2 <= next_val < 200:
                                    seq.append(next_val)
                                else:
                                    valid = False
                                    break
                            else:
                                valid = False
                                break
                        if valid and len(seq) > 10:
                            results.append(seq)
    return results

print(solve_large())
